#[global_allocator]
static GLOBAL: mimalloc::MiMalloc = mimalloc::MiMalloc;

use std::cell::{Cell, RefCell};
use std::collections::HashMap;
use std::io::{Read, Write};
use std::rc::Rc;

mod xlsx;
mod parse;
mod eval;
mod fmt;
mod funcs;

pub use eval::*;
pub use parse::*;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Er {
    Div0,
    Value,
    NA,
    Num,
    Ref,
    Name,
    Null,
}

impl Er {
    pub fn code(self) -> &'static str {
        match self {
            Er::Div0 => "#DIV/0!",
            Er::Value => "#VALUE!",
            Er::NA => "#N/A",
            Er::Num => "#NUM!",
            Er::Ref => "#REF!",
            Er::Name => "#NAME?",
            Er::Null => "#NULL!",
        }
    }
}

#[derive(Clone, Debug)]
pub enum Val {
    N(f64),
    S(Rc<str>),
    B(bool),
    E(Er),
    Empty,
}

pub struct Sheet {
    pub name: String,
    pub nrows: usize,
    pub ncols: usize,
    pub cells: Vec<Val>,
    pub fidx: Vec<u32>, // u32::MAX none
}

impl Sheet {
    #[inline]
    pub fn idx(&self, r: usize, c: usize) -> Option<usize> {
        if r < self.nrows && c < self.ncols {
            Some(r * self.ncols + c)
        } else {
            None
        }
    }
}

pub struct Formula {
    pub sheet: usize,
    pub row: u32,
    pub col: u32,
    pub text: String,
    pub expr: Option<Expr>,
    pub state: Cell<u8>, // 0 none, 1 computing, 2 done
    pub val: RefCell<Val>,
}

pub struct Book {
    pub sheets: Vec<Sheet>,
    pub formulas: Vec<Formula>,
    pub sheet_names: HashMap<String, usize>,
}

fn col_name(mut c: usize) -> String {
    let mut s = Vec::new();
    c += 1;
    while c > 0 {
        let r = (c - 1) % 26;
        s.push(b'A' + r as u8);
        c = (c - 1) / 26;
    }
    s.reverse();
    String::from_utf8(s).unwrap()
}

fn json_escape(s: &str, out: &mut String) {
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('"');
}

fn run(inp: &str, outp: &str) {
    let mut book = xlsx::load(inp);
    // parse formulas
    for i in 0..book.formulas.len() {
        let e = parse::parse_formula(&book.formulas[i].text, &book.sheet_names, book.formulas[i].sheet);
        book.formulas[i].expr = e;
    }
    let ctx = Ctx { book: &book };
    let mut out = String::with_capacity(1 << 20);
    out.push('{');
    let mut first_sheet = true;
    for (si, sh) in book.sheets.iter().enumerate() {
        if !first_sheet {
            out.push(',');
        }
        first_sheet = false;
        json_escape(&sh.name, &mut out);
        out.push_str(":{");
        let mut first = true;
        for (fi, f) in book.formulas.iter().enumerate() {
            if f.sheet != si {
                continue;
            }
            let v = ctx.formula_value(fi);
            if !first {
                out.push(',');
            }
            first = false;
            out.push('"');
            out.push_str(&col_name(f.col as usize));
            out.push_str(&(f.row + 1).to_string());
            out.push_str("\":");
            match v {
                Val::N(n) => {
                    if n.is_finite() {
                        out.push_str("{\"t\":\"n\",\"v\":");
                        if n == n.trunc() && n.abs() < 1e15 {
                            out.push_str(&format!("{}", n as i64));
                        } else {
                            out.push_str(&format!("{:e}", n));
                        }
                        out.push('}');
                    } else {
                        out.push_str("{\"t\":\"e\",\"v\":\"#NUM!\"}");
                    }
                }
                Val::S(s) => {
                    out.push_str("{\"t\":\"s\",\"v\":");
                    json_escape(&s, &mut out);
                    out.push('}');
                }
                Val::B(b) => {
                    out.push_str(if b { "{\"t\":\"b\",\"v\":true}" } else { "{\"t\":\"b\",\"v\":false}" });
                }
                Val::E(e) => {
                    out.push_str("{\"t\":\"e\",\"v\":\"");
                    out.push_str(e.code());
                    out.push_str("\"}");
                }
                Val::Empty => {
                    out.push_str("{\"t\":\"n\",\"v\":0}");
                }
            }
        }
        out.push('}');
    }
    out.push('}');
    let mut f = std::fs::File::create(outp).expect("create out");
    f.write_all(out.as_bytes()).unwrap();
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let mut inp = String::new();
    let mut outp = String::from("values.json");
    let mut i = 1;
    while i < args.len() {
        match args[i].as_str() {
            "--in" => {
                inp = args[i + 1].clone();
                i += 1;
            }
            "--out" => {
                outp = args[i + 1].clone();
                i += 1;
            }
            _ => {}
        }
        i += 1;
    }
    let child = std::thread::Builder::new()
        .stack_size(4 << 30)
        .spawn(move || run(&inp, &outp))
        .unwrap();
    child.join().unwrap();
}

