    let ss = secs % 60;
    let wd = ((serial + 6).rem_euclid(7)) as usize; // 0=Sunday; serial 0 = Saturday(6)
    let lf: Vec<char> = f.chars().collect();
    let mut out = String::new();
    let mut i = 0;
    // detect 'am/pm'
    while i < lf.len() {
