                    }
                } else if c == '0' {
                    int_digits += 1;
                }
            }
            '.' => in_dec = true,
            ',' => has_comma = true,
            '%' => {
                has_percent = true;
                if seen_digit {
                    suffix.push('%');
                } else {
                    prefix.push('%');
                }
            }
            'E' | 'e' => {
                if i + 1 < chars.len() && (chars[i + 1] == '+' || chars[i + 1] == '-') {
                    in_exp = true;
                    in_dec = false;
                    exp_plus = chars[i + 1] == '+';
                    i += 1;
                }
            }
            '"' => {
                i += 1;
                while i < chars.len() && chars[i] != '"' {
                    if seen_digit {
