                while s.ends_with('0') && s.len() > 0 {
                    let decs = s.len() - s.find('.').unwrap() - 1;
                    if decs <= dec_digits {
                        break;
                    }
                    s.pop();
                }
                if s.ends_with('.') {
                    s.pop();
                }
            }
        }
        let (ip, dp) = match s.split_once('.') {
            Some((a, b)) => (a.to_string(), Some(b.to_string())),
            None => (s.clone(), None),
        };
        let mut ip = ip;
        if ip == "0" && int_digits == 0 {
            ip = String::new();
        }
