            ip.insert(0, '0');
        }
        if has_comma {
            ip = group_thousands(&ip);
        }
        body.push_str(&ip);
        if let Some(dp) = dp {
            body.push('.');
            body.push_str(&dp);
        }
        if neg && body.chars().any(|c| c.is_ascii_digit() && c != '0') {
            body.insert(0, '-');
        } else if neg && body.is_empty() {
        }
    }
    if neg && (in_exp || exp_digits > 0) {
        body.insert(0, '-');
    }
    Some(format!("{}{}{}", prefix, body, suffix))
}

